(function(){
  const ORDER_ID='SL2026091209';
  const state={items:[],ack:false,status:'PENDING',loaded:false};
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const count=()=>state.items.filter(x=>x.checked).length;
  const diff=x=>Number(x.receivedQty)!==Number(x.deliveryQty);
  function status(){const el=document.getElementById('checklistStatus');if(!el)return;el.textContent=state.status==='ACCEPTED'?`已验收 · ${count()}/${state.items.length}`:`${count()}/${state.items.length} 已核对`;el.className='tag '+(state.status==='ACCEPTED'?'green':'orange');}
  function render(){const host=document.getElementById('checklistItems');host.innerHTML=state.items.map(x=>`<div class="check-row ${x.checked?'done ':''}${diff(x)?'diff':''}"><div class="check-main"><input type="checkbox" data-code="${x.code}" class="check" ${x.checked?'checked':''} aria-label="确认${esc(x.name)}验收"/><div><div class="check-line"><span class="check-code">${esc(x.code)}</span><span class="check-name">${esc(x.name)}</span></div><div class="check-meta">批次 ${esc(x.batch)} · ${esc(x.unit)} · 送货 ${x.deliveryQty}</div></div><div><div class="check-label">实收</div><input data-code="${x.code}" class="qty field check-qty" type="number" min="0" value="${x.receivedQty}" aria-label="${esc(x.name)}实收数量"/></div></div>${diff(x)?`<input data-code="${x.code}" class="reason field check-reason" placeholder="请填写差异原因" value="${esc(x.reason||'')}" aria-label="${esc(x.name)}差异原因"/>`:''}</div>`).join('');status();}
  function notify(m,err){const e=document.getElementById('checklistMsg');e.textContent=m;e.className='text-xs min-h-5 '+(err?'text-red-600':'text-emerald-700');if(window.t)t(m)}
  function load(){if(state.loaded)return;state.loaded=true;AppApi.getChecklist(ORDER_ID).then(r=>{const d=r&&r.data||{};state.items=(d.items||[]).map(x=>({...x,receivedQty:Number(x.receivedQty)||0,checked:!!x.checked,reason:''}));document.getElementById('checklistLoading').classList.add('hidden');document.getElementById('checklistPanel').classList.remove('hidden');render()})}
  window.openChecklist=function(){goTab('check');load()};window.saveChecklistDraft=function(){localStorage.setItem('wms_mobile_checklist_draft',JSON.stringify(state));notify('验收草稿已保存')};window.confirmChecklist=function(){if(count()!==state.items.length)return notify('请逐项勾选核对清单',true);if(!document.getElementById('checklistAck').checked)return notify('请勾选核对声明',true);if(state.items.some(x=>diff(x)&&!String(x.reason||'').trim()))return notify('数量有差异时必须填写原因',true);AppApi.confirmChecklist({orderId:ORDER_ID,items:state.items,operator:'李晓明',deviceId:'PDA-03'}).then(r=>{if(r&&r.ok){state.status='ACCEPTED';status();notify('清单验收已提交')}else notify((r&&r.msg)||'提交失败',true)})};
  document.addEventListener('DOMContentLoaded',()=>{document.getElementById('checklistPanel').addEventListener('input',e=>{const x=state.items.find(i=>i.code===e.target.dataset.code);if(!x)return;if(e.target.classList.contains('qty'))x.receivedQty=Number(e.target.value)||0;if(e.target.classList.contains('reason'))x.reason=e.target.value;render()});document.getElementById('checklistPanel').addEventListener('change',e=>{const x=state.items.find(i=>i.code===e.target.dataset.code);if(x&&e.target.classList.contains('check')){x.checked=e.target.checked;render()}})});
})();
